import * as art from './art.js';
import {AREAS,isBlocked,allQuestWolves} from './world.js';
import {Battle} from './combat.js';
import {Voices} from './audio.js';
import {freshState,loadState,saveState,canTravel,questText,defeatWolf,completeQuest} from './state.js';

const $=id=>document.getElementById(id);
const canvas=$('game'),ctx=canvas.getContext('2d',{alpha:false});
ctx.imageSmoothingEnabled=false;
const W=960,H=540,keys=new Set(),voices=new Voices(),thumbs=new Map();
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const hash=(x,y)=>{let n=Math.imul(x+374761393,y+668265263);n=(n^(n>>>13))*1274126177;return (n^(n>>>16))>>>0;};
let saved=loadState(),s=saved||freshState(),screen='home',overlay=null,dialog=null,battle=null,battleTarget=null,pendingBattle=null,nearest=null;
let time=0,lastTime=performance.now(),saveTimer=0,introTimer=0,toastTimer=0,mapArea='town',walkTime=0,facing='down',walking=false;
let camera={x:0,y:0},battleBackdrop=null,storageWarningShown=false;
const overlays=['notice','map-screen','pause','gameover','complete'];

function safeSave(){if(!saveState(s)&&!storageWarningShown){storageWarningShown=true;toast('Your browser could not save progress. Keep this tab open.');}saved=structuredClone(s);}
function showOverlay(id){overlay=id;introTimer=0;$('area-intro').hidden=true;for(const x of overlays)$(x).hidden=x!==id;keys.clear();$('interaction-prompt').hidden=true;}
function closeOverlay(){overlay=null;for(const x of overlays)$(x).hidden=true;keys.clear();}
function toast(text,duration=4){$('toast').textContent=text;$('toast').hidden=false;toastTimer=duration;}
function refreshHome(){saved=loadState()||saved;$('freeplay').hidden=!saved?.completed;$('home-save').textContent=saved?.completed?'One emerald earned. A whole valley to explore.':saved?'Your adventure is waiting.':'A sword, a notice, and a little courage.';}
function home(navigate=true){if(navigate&&/\/(chapters|play)\.html$/.test(location.pathname)){location.href='./index.html';return;}screen='home';dialog=null;battle=null;pendingBattle=null;closeOverlay();$('dialogue').hidden=true;$('hud').hidden=true;$('home').hidden=false;$('chapters').hidden=true;$('area-intro').hidden=true;$('toast').hidden=true;$('mobile-controls').style.visibility='hidden';keys.clear();refreshHome();}
function chapters(){if(!location.pathname.endsWith('/chapters.html')){location.href='./chapters.html';return;}screen='chapters';$('home').hidden=true;$('chapters').hidden=false;$('hud').hidden=true;$('chapter-card').disabled=!!saved?.completed;$('chapter-badge').textContent=saved?.completed?'CHAPTER COMPLETE':'CHAPTER ONE';$('chapter-action').innerHTML=saved?.completed?'Completed · free play unlocked':saved?'Continue chapter <span>✦</span>':'Begin chapter <span>✦</span>';if(!thumbs.has('chapter'))thumbs.set('chapter',makeThumbnail('town',true));$('chapter-image').src=thumbs.get('chapter');}
function start(mode='chapter'){
 if(!location.pathname.endsWith('/play.html')){location.href='./play.html?mode='+mode;return;}
 voices.unlock();s=loadState()||saved||freshState();
 if(mode==='chapter'&&s.completed){toast('Chapter One is complete. Explore in free play.');return;}
 if(mode==='freeplay'){if(!s.completed)return;s.mode='freeplay';s.area='town';s.x=null;s.y=null;s.hp=25;}else s.mode='chapter';
 if(!AREAS[s.area])s.area='town';const a=AREAS[s.area];if(!Number.isFinite(s.x)||!Number.isFinite(s.y)||isBlocked(s.area,s.x,s.y,8)){s.x=a.spawn.x;s.y=a.spawn.y;}
 screen='world';$('home').hidden=true;$('chapters').hidden=true;$('hud').hidden=false;$('mobile-controls').style.visibility='visible';closeOverlay();setCamera(true);updateHUD();areaIntro();safeSave();
 if(s.stage==='meet')toast('Walk to the tavern. E talks, reads, and opens doors.',6);
}
function areaIntro(){const a=AREAS[s.area];$('area-title').textContent=a.label;$('area-subtitle').textContent=a.subtitle||'THE BRAMBLEWICK VALLEY';$('area-intro').hidden=false;introTimer=3.5;}
function enterArea(id,x,y){if(!AREAS[id])return;const a=AREAS[id];s.area=id;s.x=x??a.spawn.x;s.y=y??a.spawn.y;if(!s.visited.includes(id))s.visited.push(id);nearest=null;setCamera(true);areaIntro();updateHUD();safeSave();}
function setCamera(immediate=false){const a=AREAS[s.area];const desired={x:clamp(s.x-W/2,0,Math.max(0,a.width-W)),y:clamp(s.y-H/2,0,Math.max(0,a.height-H))};if(a.width<W)desired.x=-(W-a.width)/2;if(a.height<H)desired.y=-(H-a.height)/2;if(immediate)camera=desired;else{camera.x+=(desired.x-camera.x)*.16;camera.y+=(desired.y-camera.y)*.16;}}
function updateHUD(){const a=AREAS[s.area];$('area-name').textContent=a.label.toUpperCase();$('quest-label').textContent=s.mode==='freeplay'?'FREE PLAY':'CHAPTER ONE';$('objective-text').textContent=questText(s,allQuestWolves.length);$('health-text').textContent=`${s.hp} / 25`;$('health-fill').style.width=`${s.hp/25*100}%`;drawMap($('minimap').getContext('2d'),s.area,132,132,true);}

function say(lines,onDone){if(!lines?.length){onDone?.();return;}dialog={lines:lines.map(l=>typeof l==='string'?{speaker:'Yips',text:l}:l),index:0,chars:0,clock:0,onDone};$('dialogue').hidden=false;$('interaction-prompt').hidden=true;keys.clear();renderDialogueLine();}
function renderDialogueLine(){const l=dialog.lines[dialog.index];dialog.chars=0;dialog.clock=0;$('speaker').textContent=l.speaker||'Yips';$('dialogue-text').textContent='';$('dialogue-choices').replaceChildren();$('dialogue-next').hidden=false;const c=$('dialogue-portrait').getContext('2d');c.clearRect(0,0,94,104);const type=l.speaker==='Bram'?'keeper':l.speaker==='Witch'?'witch':l.speaker==='Wolf'?'wolf':l.speaker==='Yips'?'yips':'villager';art.drawSprite(c,type,47,91,{scale:1.4,time});}
function revealChoices(){const l=dialog.lines[dialog.index];if(!l.choices?.length)return;$('dialogue-next').hidden=true;if($('dialogue-choices').childElementCount)return;for(const choice of l.choices){const b=document.createElement('button');b.textContent=choice.text;b.onclick=()=>{dialog=null;$('dialogue').hidden=true;choice.action();};$('dialogue-choices').append(b);}}
function advanceDialogue(){if(!dialog)return;const l=dialog.lines[dialog.index];if(dialog.chars<l.text.length){dialog.chars=l.text.length;$('dialogue-text').textContent=l.text;revealChoices();return;}if(l.choices){revealChoices();return;}if(++dialog.index<dialog.lines.length){renderDialogueLine();return;}const done=dialog.onDone;dialog=null;$('dialogue').hidden=true;keys.clear();done?.();updateHUD();}
function tickDialogue(dt){if(!dialog)return;const l=dialog.lines[dialog.index];dialog.clock+=dt;const interval=l.speaker==='Bram'?.038:l.speaker==='Wolf'?.09:.03;while(dialog.clock>=interval&&dialog.chars<l.text.length){dialog.clock-=interval;const char=l.text[dialog.chars++];voices.speak(l.speaker||'Yips',char);$('dialogue-text').textContent=l.text.slice(0,dialog.chars);if(/[.!?]/.test(char))dialog.clock-=.14;}if(dialog.chars>=l.text.length)revealChoices();}

function keeper(){
 if(s.mode==='freeplay'){say([{speaker:'Bram',text:'Hey, Yips. The usual table is free. What is on your mind?',choices:[{text:'The forest',action:()=>say([{speaker:'Yips',text:'How is the forest doing?'},{speaker:'Bram',text:'Travelers are using the road again. Yesterday someone complained about ordinary mud. Best complaint I have heard all week.'}])},{text:'The emerald',action:()=>say([{speaker:'Yips',text:'I still have that emerald.'},{speaker:'Bram',text:'Good. You earned it. A small stone for a big bit of bravery.'},{speaker:'Yips',text:'It matches my scarf. That is very professional.'}])},{text:'Just visiting',action:()=>say([{speaker:'Bram',text:'Then sit a spell. No errands today, little knight. You have done enough.'}])}]}]);return;}
 if(s.stage==='meet'){say([{speaker:'Bram',text:'Hey, how is it going?'},{speaker:'Yips',text:'Good! I am Yips. I am looking for knight work. Small knight work is fine.'},{speaker:'Bram',text:'Bram. Keeper of this tavern, lifter of heavy barrels. The quest board is there, beside the shelves.'},{speaker:'Yips',text:'An actual quest board. This is already going very well.'}],()=>{s.stage='board';safeSave();});}
 else if(s.stage==='board'){say([{speaker:'Bram',text:'The note on the board, little knight. Take a look, then tell me what you think.'}]);}
 else if(s.stage==='ask'){say([{speaker:'Yips',text:'What is this? The notice about the witch?'},{speaker:'Bram',text:'Oh, that is a quest. She has been brewing trouble in the pine forest. Wolves on every bend. Nobody can get through.'},{speaker:'Bram',text:'Want to take it?',choices:[{text:'Yes. I can do it.',action:acceptQuest},{text:'Let me look around.',action:()=>say([{speaker:'Bram',text:'Take your time. A sensible knight checks their boots first.'},{speaker:'Yips',text:'I should probably get boots.'}])}]}]);}
 else if(s.stage==='return'){say([{speaker:'Yips',text:'Bram! I defeated the witch. The road through the pines is safe again.'},{speaker:'Bram',text:'You did? I knew that helmet had a knight under it. Thanks for that. Here is an emerald.'},{speaker:'Yips',text:'My first reward. I am going to keep it somewhere very safe.'},{speaker:'Bram',text:'Try a pocket. I was going to suggest your ribs, but it might fall out.'}],()=>{if(completeQuest(s)){safeSave();$('completion-time').textContent=`Adventure time: ${Math.floor(s.playSeconds/60)}m ${Math.floor(s.playSeconds%60)}s` ;showOverlay('complete');}});}
 else{say([{speaker:'Bram',text:'Across the moat, then follow the old lantern road. Rest at the lanterns whenever your bones need a moment.'},{speaker:'Yips',text:`${s.wolves.length} wolves down. The rest will see my very determined helmet soon.`}]);}
}
function acceptQuest(){say([{speaker:'Bram',text:'Yes? All right. It is in the pine forest. Cross the bridge and go now, while there is still light.'},{speaker:'Bram',text:'Eight wolves guard the old road. Clear them out, then find her shack beyond the deepwood. She keeps the door sealed while her pack is out.'},{speaker:'Bram',text:'Watch where a wolf is about to scratch. Four attempts, then you strike. Rest by the trail lanterns. Come home in one piece.'},{speaker:'Yips',text:'One piece might be ambitious. But I will come home.'}],()=>{s.stage='forest';s.hp=25;s.checkpoint={area:s.area,x:s.x,y:s.y};safeSave();toast('Quest accepted: The Pinewood Witch',5);});}
function inspectBoard(){if(s.mode==='freeplay'){say([{speaker:'Yips',text:'The note has a big COMPLETED stamp. I keep checking. It still feels good.'}]);return;}showOverlay('notice');}
function closeNotice(){closeOverlay();if(s.stage==='meet'||s.stage==='board'){s.stage='ask';safeSave();}say([{speaker:'Yips',text:'Defeat a witch. One emerald. I should ask Bram about this.'}]);}
function wolf(target){if(s.mode==='freeplay'||s.wolves.includes(target.id))return;if(!['forest','witch'].includes(s.stage)){say([{speaker:'Yips',text:'I should ask Bram about the forest before going any farther.'}]);return;}say([{speaker:'Wolf',text:'Bark!'},{speaker:'Yips',text:s.wolves.length===0?'Hello. I am looking for a witch. You are looking at my bones. That is unfortunate.':'All right. I know that look. No chewing the knight.'},{speaker:'Wolf',text:'Bark! Bark!'}],()=>startBattle(target,'wolf'));}
function witch(target){if(s.mode==='freeplay'||s.stage==='return'||s.completed){say([{speaker:'Yips',text:'Empty bottles. A cold cauldron. The forest feels lighter already.'}]);return;}if(s.wolves.length<allQuestWolves.length){say([{speaker:'Yips',text:'Her spell is still tied to the wolves outside. I need to clear the whole road.'}]);return;}say([{speaker:'Witch',text:'A little skeleton with a little sword. Did the tavern run out of real knights?'},{speaker:'Yips',text:'I am the knight. Your wolves are frightening everyone. You need to stop.'},{speaker:'Witch',text:'My forest. My road. My very carefully labeled potions. Let us see how well you dodge.'},{speaker:'Yips',text:'I have been practicing.'},{speaker:'Witch',text:'Count five, little bones. That is when the bottles bloom.'}],()=>startBattle(target,'witch'));}
function interact(){if(screen!=='world')return;voices.unlock();if(overlay==='notice'){closeNotice();return;}if(overlay)return;if(dialog){advanceDialogue();return;}if(battle){battle.attack();return;}if(!nearest)return;const n=nearest;
 if(n.kind==='keeper')return keeper();if(n.kind==='board')return inspectBoard();if(n.kind==='wolf')return wolf(n);if(n.kind==='witch')return witch(n);
 if(n.kind==='rest'){s.hp=25;s.checkpoint={area:s.area,x:s.x,y:s.y};if(!s.rests.includes(n.id))s.rests.push(n.id);safeSave();say([{speaker:'Yips',text:n.lines?.[0]?.text||'A warm lantern, a quiet patch of moss. I can put myself back together here.'},{speaker:'Yips',text:'All twenty-five hit points. All my usual bones.'}]);updateHUD();return;}
 if(n.kind==='door'||n.kind==='exit'){
   if(n.toArea==='forest'&&s.stage==='meet'&&s.mode!=='freeplay'){say([{speaker:'Yips',text:'Before I explore the woods, I should find the tavern keeper. He might know about knight work.'}]);return;}
   if(n.id==='den-door'&&s.mode!=='freeplay'&&s.wolves.length<allQuestWolves.length){say([{speaker:'Witch',text:`My pack still roams, little knight. ${allQuestWolves.length-s.wolves.length} wolves keep this seal strong.`},{speaker:'Yips',text:'Back to the old road. My map will show who I missed.'}]);return;}
   enterArea(n.toArea,n.toX,n.toY);return;
 }
 const lines=n.lines||n.dialogue||[{speaker:n.speaker||'Yips',text:n.text||'Every little corner of this place has a story.'}];say(lines);
}
function startBattle(target,type){battleTarget=target;battleBackdrop=document.createElement('canvas');battleBackdrop.width=W;battleBackdrop.height=H;battleBackdrop.getContext('2d').drawImage(canvas,0,0);$('hud').hidden=true;$('area-intro').hidden=true;keys.clear();battle=new Battle({type,playerHp:s.hp,onFinish:result=>{pendingBattle={...result,delay:result.won?1.1:.45};}});battle.reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;}
function finishBattle(result){pendingBattle=null;s.hp=result.playerHp;const type=result.type;battle=null;$('hud').hidden=false;if(!result.won){showOverlay('gameover');return;}if(type==='wolf'){defeatWolf(s,battleTarget.id,allQuestWolves.length);safeSave();toast(`Road cleared: ${s.wolves.length} / ${allQuestWolves.length} wolves.`,4);if(s.wolves.length===1)say([{speaker:'Yips',text:'One down. I should stop at a lantern if I need to mend. Knights are allowed a sit-down.'}]);if(s.wolves.length===allQuestWolves.length)say([{speaker:'Yips',text:'The last wolf. The spell on her door must be broken. Now for the witch.'}]);}else{s.stage='return';safeSave();say([{speaker:'Witch',text:'My bottles... my spell... that ridiculous little sword...'},{speaker:'Yips',text:'It is a small longsword. There is a difference.'},{speaker:'Yips',text:'The road is safe. Time to tell Bram. I can use my map to travel back now.'}],()=>toast('Fast travel unlocked. Open your map with M.',6));}updateHUD();}
function retry(){closeOverlay();s.hp=25;startBattle(battleTarget,battleTarget.kind==='witch'?'witch':'wolf');}
function activeEntity(n){if(n.kind==='wolf')return s.mode!=='freeplay'&&!s.wolves.includes(n.id);if(n.kind==='witch')return s.mode!=='freeplay'&&!s.completed&&s.stage!=='return';return true;}
function findNearest(){let best=null,distance=76;for(const n of AREAS[s.area].interactables){if(!activeEntity(n))continue;const d=Math.hypot(s.x-n.x,s.y-n.y);if(d<distance){best=n;distance=d;}}nearest=best;const prompt=$('interaction-prompt');prompt.hidden=!best||!!dialog||!!overlay||!!battle;if(best)prompt.querySelector('span').textContent=best.kind==='wolf'?'Face the wolf':best.kind==='witch'?'Talk to the witch':best.label||'Interact';}

function openMap(){if(screen!=='world'||battle||dialog||overlay)return;mapArea=s.area;showOverlay('map-screen');renderMapMenu();}
function renderMapMenu(){const nav=$('map-areas');nav.replaceChildren();for(const a of Object.values(AREAS)){const b=document.createElement('button');b.className=a.id===mapArea?'active':'';if(!thumbs.has(a.id))thumbs.set(a.id,makeThumbnail(a.id));const image=document.createElement('img');image.src=thumbs.get(a.id);image.alt='';const label=document.createElement('span');label.textContent=a.label;const small=document.createElement('small');small.textContent=s.area===a.id?'You are here':s.visited.includes(a.id)?'Visited':'Unexplored';label.append(small);b.append(image,label);b.onclick=()=>{mapArea=a.id;renderMapMenu();};nav.append(b);}drawMap($('large-map').getContext('2d'),mapArea,500,350,false);const locked=!canTravel(s);$('travel').disabled=locked;$('travel').hidden=locked;$('map-rule').textContent=locked?'During a chapter, follow the road on foot. Travel unlocks after the witch.':'Choose an area and travel there. The valley is yours to explore.';$('map-detail').textContent=mapArea===s.area?'The ivory bone marks your position.':AREAS[mapArea].subtitle||AREAS[mapArea].label;}
function travel(){if(!canTravel(s)||battle||dialog)return;const id=mapArea;closeOverlay();enterArea(id);toast('Arrived: '+AREAS[id].label,3);}
function drawMap(c,id,width,height,mini){const a=AREAS[id];c.clearRect(0,0,width,height);c.fillStyle='#102c30';c.fillRect(0,0,width,height);const pad=mini?8:16,scale=Math.min((width-pad*2)/a.width,(height-pad*2)/a.height);const ox=(width-a.width*scale)/2,oy=(height-a.height*scale)/2;const rect=(r,color)=>{c.fillStyle=color;c.fillRect(ox+r.x*scale,oy+r.y*scale,Math.max(1,r.w*scale),Math.max(1,r.h*scale));};c.fillStyle='#25453c';c.fillRect(ox,oy,a.width*scale,a.height*scale);for(const r of a.water||[])rect(r,'#335f70');for(const r of a.paths||[])rect(r,'#a59b67');for(const r of a.bridges||[])rect(r,'#c7ac6e');for(const b of a.buildings||[])rect(b,'#c2b38b');for(const r of a.walls||[])rect(r,'#6e8272');if(!mini)for(const t of a.trees||[]){c.fillStyle='#193a31';c.fillRect(ox+t.x*scale,oy+t.y*scale,2,2);}for(const n of a.interactables){if(n.kind==='wolf'&&!activeEntity(n))continue;if(n.kind==='witch'&&!activeEntity(n))continue;if(['exit','door','keeper','board','wolf','witch','rest'].includes(n.kind)){const x=ox+n.x*scale,y=oy+n.y*scale;c.fillStyle=n.kind==='wolf'?'#d1816d':n.kind==='rest'?'#b2d398':n.kind==='witch'?'#b8a0cf':'#e4c67a';const z=mini?2:3;c.fillRect(x-z,y-z,z*2,z*2);}}if(s.area===id){const x=ox+s.x*scale,y=oy+s.y*scale;c.fillStyle='#081921';c.fillRect(x-12,y-9,24,18);art.drawSprite(c,'bone',x,y,{scale:mini?1:1.3,time});}c.strokeStyle='#6b8268';c.lineWidth=1;c.strokeRect(.5,.5,width-1,height-1);}

function drawGround(c,a,cam,ww,hh,t){c.fillStyle=a.id==='tavern'||a.id==='den'?'#312f2b':a.id==='town'?'#334f3b':a.id==='clearing'?'#253e37':'#1d3d35';c.fillRect(cam.x,cam.y,ww,hh);const indoor=a.id==='tavern'||a.id==='den';const tile=indoor?32:24;const x0=Math.floor(Math.max(0,cam.x)/tile),y0=Math.floor(Math.max(0,cam.y)/tile),x1=Math.ceil(Math.min(a.width,cam.x+ww)/tile),y1=Math.ceil(Math.min(a.height,cam.y+hh)/tile);for(let y=y0;y<=y1;y++)for(let x=x0;x<=x1;x++){const n=hash(x,y);if(indoor){c.fillStyle=(x+y)%2?'#36362f':'#3d3b31';c.fillRect(x*tile,y*tile,tile-1,tile-1);c.fillStyle='#4a4537';c.fillRect(x*tile+3,y*tile+7,12,1);}else{c.fillStyle=n%3?'#3e5940':'#456348';c.fillRect(x*tile+n%16,y*tile+(n>>>4)%16,2,3);if(n%4===0){c.fillStyle='#64774a';c.fillRect(x*tile+8,y*tile+12,2,1);}}}
 for(const p of a.paths||[]){c.fillStyle=p.type==='wood'?'#302925':p.type==='stone'?'#60685a':'#766e4d';c.fillRect(p.x-3,p.y-3,p.w+6,p.h+6);c.fillStyle=p.type==='wood'?'#62513d':p.type==='stone'?'#81816c':'#9c8b60';c.fillRect(p.x,p.y,p.w,p.h);const left=Math.max(p.x,cam.x),top=Math.max(p.y,cam.y),right=Math.min(p.x+p.w,cam.x+ww),bottom=Math.min(p.y+p.h,cam.y+hh);for(let yy=Math.floor(top/18)*18;yy<bottom;yy+=18)for(let xx=Math.floor(left/24)*24;xx<right;xx+=24){if(xx<left||yy<top)continue;const n=hash(xx,yy);c.fillStyle=p.type==='wood'?'#473a2f':p.type==='stone'?'#656d60':n%2?'#af9b6e':'#88774f';c.fillRect(xx+(n%5),yy,5+n%7,2);if(n%3===0)c.fillRect(xx+10,yy+7,2,2);}}
 for(const r of a.water||[]){c.fillStyle='#173543';c.fillRect(r.x-4,r.y-4,r.w+8,r.h+8);c.fillStyle='#2f5963';c.fillRect(r.x,r.y,r.w,r.h);const top=Math.max(r.y,Math.floor(cam.y/18)*18),bot=Math.min(r.y+r.h,cam.y+hh),left=Math.max(r.x,cam.x),right=Math.min(r.x+r.w,cam.x+ww);for(let y=top;y<bot;y+=18){for(let x=left;x<right;x+=39){c.fillStyle='#477785';c.fillRect(x+Math.floor(Math.sin(t+y)*3),y,11,2);c.fillStyle='#244a59';c.fillRect(x+18,y+7,8,2);}}}
 for(const r of a.bridges||[]){c.fillStyle='#422f27';c.fillRect(r.x-3,r.y-3,r.w+6,r.h+6);c.fillStyle='#a18a5b';c.fillRect(r.x,r.y,r.w,r.h);for(let y=r.y;y<r.y+r.h;y+=9){c.fillStyle='#594937';c.fillRect(r.x,y,r.w,2);}c.fillStyle='#d0b379';c.fillRect(r.x+2,r.y,3,r.h);c.fillRect(r.x+r.w-5,r.y,3,r.h);}
 for(const r of a.walls||[]){c.fillStyle='#1b2a2b';c.fillRect(r.x,r.y,r.w,r.h);c.fillStyle='#617264';c.fillRect(r.x,r.y,r.w,5);for(let x=r.x+10;x<r.x+r.w;x+=26){c.fillStyle='#34483f';c.fillRect(x,r.y+6,2,r.h-6);}}
 if(indoor){c.strokeStyle='#7d7154';c.lineWidth=8;c.strokeRect(8,8,a.width-16,a.height-16);c.fillStyle='#201f23';c.fillRect(12,12,a.width-24,42);for(let x=38;x<a.width-30;x+=73){c.fillStyle='#4d4c3e';c.fillRect(x,14,5,40);}}
}
function worldScene(c,id,cam,ww,hh,t,player=true){const a=AREAS[id];c.save();c.imageSmoothingEnabled=false;c.fillStyle='#0c1e24';c.fillRect(0,0,ww,hh);c.translate(-Math.floor(cam.x),-Math.floor(cam.y));drawGround(c,a,cam,ww,hh,t);const visible=(x,y,margin=150)=>x>cam.x-margin&&x<cam.x+ww+margin&&y>cam.y-margin&&y<cam.y+hh+margin;const items=[];for(const b of a.buildings||[])if(visible(b.x+b.w/2,b.y+b.h,b.w))items.push({y:b.y+b.h,draw:()=>art.drawBuilding(c,b)});for(const p of a.props||[])if(visible(p.x,p.y)){if(p.type==='rug')art.drawProp(c,p,t);else items.push({y:p.y,draw:()=>art.drawProp(c,p,t)});}for(const tr of a.trees||[])if(visible(tr.x,tr.y))items.push({y:tr.y,draw:()=>art.drawTree(c,tr.x,tr.y,tr.seed)});for(const n of a.interactables){if(!visible(n.x,n.y)||!activeEntity(n))continue;const type=({keeper:'keeper',wolf:'wolf',witch:'witch',npc:'villager'})[n.kind];if(type)items.push({y:n.y,draw:()=>{art.drawSprite(c,type,n.x,n.y,{time:t,variant:hash(n.x,n.y)%4});if(n.kind==='keeper'&&s.stage==='meet'){c.fillStyle='#efd786';c.fillRect(n.x-2,n.y-58,4,10);c.fillRect(n.x-2,n.y-45,4,3);}}});}
 if(player){const px=id===s.area?s.x:a.spawn.x,py=id===s.area?s.y:a.spawn.y;items.push({y:py,draw:()=>art.drawSprite(c,'yips',px,py,{time:walkTime,walking:id===s.area&&walking,facing})});}items.sort((a,b)=>a.y-b.y);for(const i of items)i.draw();if(id==='forest'||id==='deepwood'||id==='clearing'){for(let i=0;i<22;i++){const x=cam.x+((i*127+t*(i%3+2))%ww),y=cam.y+((i*89+Math.sin(t+i)*15)%hh);c.fillStyle=i%4===0?'#b6be7733':'#adcab01a';c.fillRect(x,y,2,2);}}c.restore();}
function makeThumbnail(id,chapter=false){const a=AREAS[id],c=document.createElement('canvas');c.width=chapter?600:240;c.height=chapter?300:140;const d=c.getContext('2d');d.imageSmoothingEnabled=false;let focus=a.spawn;if(chapter){const door=a.interactables.find(n=>n.toArea==='tavern');if(door)focus={x:door.x,y:door.y-50};}else if(id==='clearing'){const door=a.interactables.find(n=>n.id==='den-door');if(door)focus={x:door.x,y:door.y-40};}const cam={x:clamp(focus.x-c.width/2,0,Math.max(0,a.width-c.width)),y:clamp(focus.y-c.height/2,0,Math.max(0,a.height-c.height))};worldScene(d,id,cam,c.width,c.height,0,false);if(chapter)art.drawSprite(d,'yips',c.width/2,c.height*.8,{scale:1.3});return c.toDataURL('image/png');}

function inputVector(){let x=Number(keys.has('d')||keys.has('ArrowRight'))-Number(keys.has('a')||keys.has('ArrowLeft')),y=Number(keys.has('s')||keys.has('ArrowDown'))-Number(keys.has('w')||keys.has('ArrowUp'));const length=Math.hypot(x,y);if(length){x/=length;y/=length;}return{x,y,focus:keys.has('Shift')};}
function move(dt){const v=inputVector();walking=!!(v.x||v.y);if(!walking)return;walkTime+=dt;if(Math.abs(v.x)>Math.abs(v.y))facing=v.x>0?'right':'left';else facing=v.y>0?'down':'up';const amount=130*dt;const a=AREAS[s.area],nx=clamp(s.x+v.x*amount,12,a.width-12),ny=clamp(s.y+v.y*amount,12,a.height-12);if(!isBlocked(s.area,nx,s.y,8))s.x=nx;if(!isBlocked(s.area,s.x,ny,8))s.y=ny;}
function tick(now){const dt=Math.min((now-lastTime)/1000,.05);lastTime=now;time+=dt;if(screen==='world'){if(!overlay){s.playSeconds+=dt;if(dialog)tickDialogue(dt);else if(battle){battle.update(dt,inputVector());if(pendingBattle){pendingBattle.delay-=dt;if(pendingBattle.delay<=0)finishBattle(pendingBattle);}}else{move(dt);setCamera();findNearest();}}else walking=false;
   $('battle-attack').hidden=!battle||!!overlay||battle.phase!=='attack';$('battle-pause').hidden=!battle||!!overlay;if(battle){battle.draw(ctx,art,time);}else worldScene(ctx,s.area,camera,W,H,time,true);
   if(!battle&&!overlay&&!dialog){saveTimer+=dt;if(saveTimer>3){saveTimer=0;safeSave();}if(Math.floor(time*10)!==Math.floor((time-dt)*10))updateHUD();}
 }else {art.drawTitleScene(ctx,W,H,time);if(screen==='home'){ctx.fillStyle='#0817208a';ctx.fillRect(0,0,W,H);}}
 if(introTimer>0){introTimer-=dt;if(introTimer<=0)$('area-intro').hidden=true;else $('area-intro').style.opacity=String(Math.min(1,introTimer));}
 if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').hidden=true;}
 requestAnimationFrame(tick);
}
function onKey(key,repeat=false){voices.unlock();if(key==='e'||key==='Enter'||key===' '){if(!repeat){if(screen==='home')chapters();else if(screen==='chapters'&&!saved?.completed)start();else interact();}return;}if(key==='m'&&!repeat){if(overlay==='map-screen')closeOverlay();else openMap();return;}if(key==='Escape'&&!repeat){if(overlay==='pause'||overlay==='map-screen')closeOverlay();else if(overlay==='notice')closeNotice();else if(screen==='chapters')home();else if(screen==='world'&&!overlay&&!dialog)showOverlay('pause');}}
document.addEventListener('keydown',e=>{const key=e.key.length===1?e.key.toLowerCase():e.key;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','Tab'].includes(key)&&key!=='Tab')e.preventDefault();if(e.target instanceof HTMLButtonElement&&(key==='Enter'||key===' '))return;keys.add(key);onKey(key,e.repeat);});
document.addEventListener('keyup',e=>keys.delete(e.key.length===1?e.key.toLowerCase():e.key));
window.addEventListener('blur',()=>{keys.clear();if(screen==='world'&&!overlay&&!dialog)showOverlay('pause');});
document.addEventListener('visibilitychange',()=>{keys.clear();if(document.hidden&&screen==='world'){safeSave();if(!overlay)showOverlay('pause');}lastTime=performance.now();});
window.addEventListener('beforeunload',()=>{if(screen==='world'&&s.hp>0)safeSave();});
document.addEventListener('pointerdown',()=>voices.unlock(),{once:true});
$('start').onclick=()=>{voices.unlock();chapters();};$('freeplay').onclick=()=>start('freeplay');$('chapter-card').onclick=()=>start();for(const b of document.querySelectorAll('[data-action="home"]'))b.onclick=home;
$('interaction-prompt').onclick=interact;$('battle-attack').onclick=()=>battle?.attack();$('battle-pause').onclick=()=>showOverlay('pause');$('dialogue-next').onclick=advanceDialogue;$('notice-close').onclick=closeNotice;$('minimap-button').onclick=openMap;$('map-close').onclick=closeOverlay;$('travel').onclick=travel;$('pause-button').onclick=()=>showOverlay('pause');$('resume').onclick=closeOverlay;$('voices').onclick=()=>{voices.enabled=!voices.enabled;$('voices').textContent='Dialogue sounds: '+(voices.enabled?'on':'off');};$('save-home').onclick=()=>{safeSave();home();};$('retry').onclick=retry;$('defeat-home').onclick=()=>{s.hp=25;safeSave();home();};$('complete-home').onclick=home;
if(matchMedia('(pointer: coarse)').matches)document.body.classList.add('touch');
for(const b of document.querySelectorAll('[data-key]')){b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.key);onKey(b.dataset.key);};b.onpointerup=b.onpointercancel=()=>keys.delete(b.dataset.key);}
const logo=$('logo').getContext('2d');art.pixelText(logo,'BONE',3,5,9,'#0c181c');art.pixelText(logo,'BONE',0,0,9,'#f0dfae');art.pixelText(logo,'KNIGHT',3,88,8,'#0c181c');art.pixelText(logo,'KNIGHT',0,82,8,'#e3ba6c');
art.pixelText($('chapter-heading').getContext('2d'),'CHAPTERS',0,4,5,'#eee1b9');art.drawSprite($('yips-portrait').getContext('2d'),'yips',70,137,{scale:3});
prepareHomeGallery();home(false);if(location.pathname.endsWith('/chapters.html'))chapters();if(location.pathname.endsWith('/play.html'))start(new URLSearchParams(location.search).get('mode')==='freeplay'?'freeplay':'chapter');requestAnimationFrame(tick);

