 const c=document.createElement('canvas');c.width=700;c.height=500;const d=c.getContext('2d');worldScene(d,'tavern',{x:0,y:0},700,500,0,false);art.drawSprite(d,'yips',350,265,{time:0});$('tavern-shot').src=c.toDataURL('image/png');
 const detail=document.createElement('canvas');detail.width=280;detail.height=175;const e=detail.getContext('2d');worldScene(e,'tavern',{x:420,y:70},280,175,0,false);art.drawSprite(e,'yips',146,157,{time:0,facing:'up'});$('tavern-detail').src=detail.toDataURL('image/png');
